const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// ─────────────────────────────────────────────────────────────────────────\n// Electro Zaki Storefront — Prisma Schema (v1)\n// Datasource: Neon (Postgres), accessed via Prisma from Next.js (App Router)\n// ─────────────────────────────────────────────────────────────────────────\n//\n// DESIGN RULE (read this before touching the storefront code):\n// `Product` is the ONLY model the public storefront (product pages, search,\n// collections) is allowed to query. `ProductInternal` holds everything\n// staff-only (cost, supplier, margin, exact stock count). Never `include`\n// or `select` ProductInternal from any file under `app/(storefront)`.\n// The safest way to enforce this in code (built in deliverable 2) is a\n// single `lib/db/public-products.ts` file that is the *only* place allowed\n// to import the Prisma client for product reads on the public side, and\n// whose functions hard-code the field list — so a future developer adding\n// `purchasePrice` to a page has to notice they're bypassing that file.\n// ─────────────────────────────────────────────────────────────────────────\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // No `url`/`directUrl` here — Prisma 7's driver-adapter architecture takes\n  // the app's connection from the adapter (lib/db/client.ts) and the CLI's\n  // connection from prisma.config.ts, not from this file.\n}\n\n// ── Enums ───────────────────────────────────────────────────────────────\n\n// 4-tier grading standard from the phase-2 spec, replacing the earlier\n// NEW/REFURBISHED/USED. This is a breaking rename — every place that reads\n// ProductCondition (product page, ProductCard) needs updating alongside it.\nenum ProductCondition {\n  NEUF\n  TRES_BON\n  BON\n  PIECES_REMPLACEES\n}\n\n// Deliberately NOT the ERP's Arabic operational enum (متوفر/مباع/إصلاح/...).\n// That enum describes a phone's position in a POS workflow (sold, mid-repair,\n// mid-exchange, in transfer). A storefront listing only ever needs to say\n// \"can a customer request this right now\" — so it gets its own, simpler enum.\nenum AvailabilityStatus {\n  IN_STOCK\n  OUT_OF_STOCK\n  COMING_SOON // matches the current \"coming soon\" placeholder on accessory collections\n  DISCONTINUED\n}\n\n// Where a product's stock and price come from. ERP products are created and\n// kept up to date by the ERP's sync (electrozaki_terminal,\n// src/lib/storefront/sync.ts): staff never edit their price/stock/condition\n// here — only the presentation (photos, description, category, published).\nenum ProductSource {\n  MANUAL\n  ERP\n}\n\nenum OrderRequestStatus {\n  NEW\n  CONTACTED\n  CONFIRMED\n  CANCELLED\n}\n\n// ── Catalog ─────────────────────────────────────────────────────────────\n\n// A flat-or-nested category tree, so \"Accessoires\" can have children like\n// Pochettes / Incassables / Câbles / Chargeurs / Oraimo without hardcoding\n// them as an enum (new subcategories are then a data change, not a deploy).\nmodel Category {\n  id        String     @id @default(cuid())\n  name      String\n  slug      String     @unique\n  // The ERP accessory-category code (or \"telephone\") this category receives\n  // synced products for. Null for purely hand-made categories.\n  erpCode   String?    @unique\n  parentId  String?\n  parent    Category?  @relation(\"CategoryToCategory\", fields: [parentId], references: [id])\n  children  Category[] @relation(\"CategoryToCategory\")\n  sortOrder Int        @default(0)\n  products  Product[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([parentId])\n}\n\n// The PUBLIC product view. Every field here is safe to render on the site.\nmodel Product {\n  id          String           @id @default(cuid())\n  slug        String           @unique\n  name        String\n  brand       String?\n  condition   ProductCondition\n  description String?          @db.Text\n\n  // Drives the checkout's dynamic payment logic (phase-2): an order needs\n  // the 300 DH advance if ANY item has isPhone=true. Deliberately an\n  // explicit staff-set flag rather than inferred from category name/slug,\n  // which would silently break if a category gets renamed.\n  isPhone Boolean @default(false)\n\n  // Flexible spec sheet (e.g. { \"Stockage\": \"128GB\", \"RAM\": \"6GB\", \"Écran\": \"6.1\\\"\" })\n  // so phones/laptops/accessories don't need different tables for differing spec sets.\n  specs Json?\n\n  // Naming matches the ERP's \"recommended sale price\" concept for a phone,\n  // so a future shared catalog is a rename-free merge, not a remap.\n  recommendedSalePrice Decimal  @db.Decimal(10, 2)\n  compareAtPrice       Decimal? @db.Decimal(10, 2) // optional \"was\" price for promos\n\n  availability AvailabilityStatus @default(IN_STOCK)\n  tags         String[]           @default([]) // free-form search/facet keywords\n\n  // ERP link — see ProductSource. erpKey identifies the ERP group this\n  // product mirrors (a phone model+storage+grade, or one accessory); it is\n  // an opaque hash, never an ERP id. `published` = false hides the product\n  // from every public page (synced accessories start hidden until staff\n  // give them a public name).\n  source    ProductSource @default(MANUAL)\n  erpKey    String?       @unique\n  published Boolean       @default(true)\n  // Synced phones: normalised \"brand|model\" shared by every storage/grade\n  // of one model — lets staff set photos and gift options once per model.\n  modelKey  String?\n\n  // Phase-2 \"transparency\" spec: battery health is iPhone-specific in\n  // practice but kept generic here rather than a phone-only subtype: any\n  // used device with a battery can carry it, and it's just null otherwise.\n  batteryHealthPercent Int?\n  // Dashboard fields for the phase-2 \"état\" visual — null means not\n  // applicable (e.g. an accessory, or a phone with no Face ID hardware),\n  // not \"unknown\", so the UI can tell the difference and simply omit the\n  // tile rather than showing a false negative.\n  faceIdWorking        Boolean?\n  screenGenuine        Boolean?\n  batteryGenuine       Boolean?\n  // Extends the same genuine/replaced tracking to the rest of the\n  // component list the repair-request flow already uses (écran, batterie,\n  // caméra, connecteur, son) — one consistent vocabulary across the app.\n  cameraGenuine        Boolean?\n  chargingPortGenuine  Boolean?\n  speakerGenuine       Boolean?\n  hasDefects           Boolean  @default(false)\n  transparencyNotes    String?  @db.Text // shown on the PDP when hasDefects is true\n\n  metaTitle       String?\n  metaDescription String?\n\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id])\n\n  images   ProductImage[]\n  variants ProductVariant[]\n\n  // Phase-2 accessory compatibility + gift-bundle spec. A phone's\n  // `giftOptions` are its own `compatibleAccessories` filtered by\n  // `isGiftOption` — modeled as one join table so \"does this case fit that\n  // phone\" and \"which cases are free gift choices for that phone\" share the\n  // same data rather than drifting apart as two separate lists.\n  compatibleAccessories ProductCompatibility[] @relation(\"CompatibilityPhone\")\n  compatibleWithPhones  ProductCompatibility[] @relation(\"CompatibilityAccessory\")\n\n  // 1:1 to the staff-only slice. Optional at the type level only because\n  // Prisma requires it on the \"many/one\" side — every real product should\n  // have one; enforce that in the creation flow, not by making it required\n  // here (making it required here would force every public query to be\n  // capable of loading it, which is exactly what we don't want).\n  internal ProductInternal?\n\n  orderRequestItems OrderRequestItem[]\n\n  // Curated bundles this product is a member of (e.g. \"iPhone 13 + case +\n  // glass\"). See Bundle below — bundlePrice lives on the bundle, not here.\n  bundleItems BundleItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([categoryId])\n  @@index([availability])\n  @@index([published])\n  @@index([modelKey])\n}\n\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  altText   String?\n  sortOrder Int     @default(0)\n\n  @@index([productId])\n}\n\n// Optional per-product options (storage size, color, bundle, etc). A\n// product with no meaningful options simply has zero variants.\n//\n// Also doubles as \"one specific physical unit in a batch\" — a shipment of\n// otherwise-identical phones differing only by color/storage uses color +\n// storageLabel + imageUrl + stockQuantity; a shipment of individually\n// reconditioned units (each with its own replaced part and price) uses the\n// genuine/defect fields below instead. Every field here is optional and\n// falls back to the matching Product-level field when null — a variant\n// only needs to set what actually differs for that unit, not everything.\nmodel ProductVariant {\n  id            String   @id @default(cuid())\n  productId     String\n  product       Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  name          String // e.g. \"256GB — Bleu\"\n  priceOverride Decimal? @db.Decimal(10, 2) // null = use Product.recommendedSalePrice\n  skuOrRef      String?\n  // Opaque reference of the ERP unit(s) this variant mirrors (HMAC of the\n  // ERP id — never the id or IMEI itself). Lets staff find the exact phone\n  // a customer ordered.\n  erpRef        String?  @unique\n\n  // \"Clean batch\" attributes — color drives the color-swatch picker and\n  // which photo displays; storageLabel is informational (e.g. \"128GB\").\n  color         String?\n  storageLabel  String?\n  imageUrl      String?\n  // Per-variant stock — a specific color/storage combo (or a specific\n  // unit) can be sold out independently of the rest of the product.\n  stockQuantity Int     @default(0)\n\n  // \"Faulty batch\" attributes — this specific unit's condition, same\n  // vocabulary as Product's own fields.\n  batteryHealthPercent Int?\n  faceIdWorking        Boolean?\n  screenGenuine        Boolean?\n  batteryGenuine       Boolean?\n  cameraGenuine        Boolean?\n  chargingPortGenuine  Boolean?\n  speakerGenuine       Boolean?\n  hasDefects           Boolean  @default(false)\n  transparencyNotes    String?  @db.Text\n\n  orderRequestItems OrderRequestItem[]\n\n  createdAt DateTime @default(now())\n\n  @@index([productId])\n}\n\n// Links an accessory to a phone it fits. `isGiftOption` marks it as also\n// offered as one of the free choices in the phase-2 gift-bundle popup for\n// that specific phone — the accessory-page \"does this fit my phone?\"\n// selector and the phone-page \"pick your free gift\" popup both read from\n// this same table instead of two separately-maintained lists.\nmodel ProductCompatibility {\n  id String @id @default(cuid())\n\n  productId String // the accessory\n  product   Product @relation(\"CompatibilityAccessory\", fields: [productId], references: [id], onDelete: Cascade)\n\n  compatibleWithId String // the phone\n  compatibleWith   Product @relation(\"CompatibilityPhone\", fields: [compatibleWithId], references: [id], onDelete: Cascade)\n\n  isGiftOption Boolean @default(false)\n\n  createdAt DateTime @default(now())\n\n  @@unique([productId, compatibleWithId])\n  @@index([compatibleWithId])\n}\n\n// The STAFF-ONLY slice. The storefront's query layer must never import this\n// model. IMEI is deliberately excluded (an ERP-only, per-unit field) — if a\n// future merge needs per-unit serials, that's a new table added at that\n// point, not something v1 needs to carry.\nmodel ProductInternal {\n  id        String  @id @default(cuid())\n  productId String  @unique\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  // Optional: ERP-synced products never carry cost data here (it stays in\n  // the ERP) — their row only holds the stock count used to validate orders.\n  purchasePrice Decimal? @db.Decimal(10, 2)\n  minSalePrice  Decimal? @db.Decimal(10, 2) // price floor, mirrors the ERP's concept\n  supplier      String? // plain text for v1, not a Supplier table —\n  // the ERP's 4-type supplier model is ERP-only complexity\n  stockQuantity Int      @default(0)\n  sourceNote    String? // e.g. \"Douane auction\", \"reprise client\"\n  internalNotes String?  @db.Text\n\n  updatedAt DateTime @updatedAt\n}\n\n// ── Cart → WhatsApp / order-request handoff ────────────────────────────\n//\n// The cart itself is NOT modeled here — it lives client-side only (React\n// state / localStorage-free session state) until the customer submits it.\n// Submission is the moment a cart becomes durable data, as an OrderRequest.\n// This keeps the schema simple and avoids storing abandoned carts nobody\n// asked to save. If you'd rather persist in-progress carts too, say so\n// before deliverable 2 and this gets a `Cart`/`CartItem` pair added.\n\nmodel OrderRequest {\n  id               String             @id @default(cuid())\n  customerName     String\n  customerPhone    String\n  deliveryAddress  String?            @db.Text\n  status           OrderRequestStatus @default(NEW)\n  totalEstimate    Decimal            @db.Decimal(10, 2)\n  whatsappOpenedAt DateTime? // set once the WhatsApp prefill was triggered client-side\n  notes            String?            @db.Text\n\n  // Phase-2 dynamic payment tunnel. requiresAdvance is computed once at\n  // submission time from whether the cart contained an isPhone item, then\n  // stored — so a later catalog change (marking something isPhone) never\n  // silently rewrites the terms of an order already placed.\n  requiresAdvance      Boolean              @default(false)\n  advancePaymentStatus AdvancePaymentStatus @default(NOT_REQUIRED)\n  // Object key in the PRIVATE receipts bucket (never a public URL). Staff\n  // view it through a short-lived signed link generated by the ERP.\n  receiptKey           String?\n  receiptUrl           String? // legacy public URL — unused, dropped once the new code is live\n  receiptUploadedAt    DateTime?\n  dataConsentAccepted  Boolean              @default(false)\n\n  // Promo-code discount, locked in at submission time — same philosophy as\n  // requiresAdvance above: a later change to the code (or its deletion)\n  // must never rewrite the terms of an order already placed.\n  promoCodeId    String?\n  promoCode      PromoCode? @relation(fields: [promoCodeId], references: [id])\n  discountAmount Decimal    @default(0) @db.Decimal(10, 2)\n\n  items OrderRequestItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n}\n\nenum AdvancePaymentStatus {\n  NOT_REQUIRED\n  AWAITING_RECEIPT\n  RECEIPT_UPLOADED\n  VERIFIED\n  REJECTED\n}\n\nmodel OrderRequestItem {\n  id             String       @id @default(cuid())\n  orderRequestId String\n  orderRequest   OrderRequest @relation(fields: [orderRequestId], references: [id], onDelete: Cascade)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  // SetNull: a synced phone's variant is deleted once the phone is sold —\n  // unitRef below keeps the link to the exact ERP unit that was ordered.\n  variantId String?\n  variant   ProductVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  unitRef   String?\n\n  // How the line was priced by the server: a free gift for a phone in the\n  // same order, or part of a pack (bundleId).\n  isGift   Boolean @default(false)\n  bundleId String?\n\n  // Snapshots — so an edited or later-discontinued product doesn't silently\n  // rewrite the history of what was actually requested.\n  productNameSnapshot String\n  priceAtRequest      Decimal @db.Decimal(10, 2)\n  quantity            Int     @default(1)\n\n  @@index([orderRequestId])\n  @@index([productId])\n}\n\n// ── Contact page ────────────────────────────────────────────────────────\n// Simple durable log of contact-form submissions, separate from OrderRequest\n// since a contact inquiry isn't necessarily about specific products.\nmodel ContactMessage {\n  id        String   @id @default(cuid())\n  name      String\n  phone     String?\n  email     String?\n  message   String   @db.Text\n  createdAt DateTime @default(now())\n}\n\n// ── Repair diagnostic (phase-2) ─────────────────────────────────────────\n\nenum RepairRequestStatus {\n  NEW\n  CONTACTED\n  QUOTED\n  CONFIRMED\n  CANCELLED\n}\n\n// Not linked to Product — a device brought in for repair is often a model\n// we don't sell, so device info is free text rather than a Product\n// reference. problemAreas is a plain string array of area keys (ecran,\n// batterie, camera, connecteur, son, reseau) chosen from the interactive\n// diagnostic step, not user-typed.\nmodel RepairRequest {\n  id            String              @id @default(cuid())\n  customerName  String\n  customerPhone String\n  deviceBrand   String\n  deviceModel   String\n  problemAreas  String[]\n  notes         String?             @db.Text\n  status        RepairRequestStatus @default(NEW)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n}\n\n// ── Discounts & bundles ─────────────────────────────────────────────────\n\nenum PromoCodeType {\n  PERCENTAGE\n  FIXED_AMOUNT\n}\n\n// Customer-entered codes, applied in the cart before submission. Kept\n// separate from Product.compareAtPrice (the staff-set \"sale price\" shown\n// directly on a listing) — a promo code is a targeted, redeemable discount\n// rather than a standing merchandising price.\nmodel PromoCode {\n  id        String        @id @default(cuid())\n  code      String        @unique\n  type      PromoCodeType\n  value     Decimal       @db.Decimal(10, 2) // 10 means \"10%\" or \"10 MAD\", per `type`\n  active    Boolean       @default(true)\n  startsAt  DateTime?\n  expiresAt DateTime?\n\n  // Both optional — null means \"no cap\" / \"no minimum\".\n  maxRedemptions  Int?\n  redemptionCount Int      @default(0)\n  minOrderAmount  Decimal? @db.Decimal(10, 2)\n\n  orderRequests OrderRequest[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// A staff-curated set of products sold together at one combined price\n// (e.g. \"iPhone 13 + coque + verre trempé\"). Distinct from the existing\n// ProductCompatibility \"free gift\" mechanic — a bundle item is priced, not\n// free, and bundles aren't tied to exactly one phone the way gift options\n// are.\nmodel Bundle {\n  id          String  @id @default(cuid())\n  name        String\n  slug        String  @unique\n  description String? @db.Text\n  bundlePrice Decimal @db.Decimal(10, 2)\n  active      Boolean @default(true)\n\n  items BundleItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel BundleItem {\n  id       String @id @default(cuid())\n  bundleId String\n  bundle   Bundle @relation(fields: [bundleId], references: [id], onDelete: Cascade)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  quantity Int @default(1)\n\n  @@unique([bundleId, productId])\n  @@index([productId])\n}\n\n// ── ERP photos ──────────────────────────────────────────────────────────\n\n// One photo per phone model + colour, uploaded once by staff in the ERP and\n// reused by every synced product/unit of that model and colour (whatever\n// the storage or grade). modelKey is the normalised \"brand|model\".\nmodel ModelPhoto {\n  id        String   @id @default(cuid())\n  modelKey  String\n  color     String\n  url       String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([modelKey, color])\n}\n\n// ── Abuse protection ────────────────────────────────────────────────────\n\n// One row per public form submission / upload, used to cap how often a\n// single visitor (hashed IP, never the raw address) can submit. Rows older\n// than a day are pruned as new ones arrive.\nmodel RateLimitHit {\n  id        BigInt   @id @default(autoincrement())\n  bucket    String\n  keyHash   String\n  createdAt DateTime @default(now())\n\n  @@index([bucket, keyHash, createdAt])\n  @@index([createdAt])\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

